1	import { canonicalize, sha256 } from './canonicalize.ts';
2	
3	export const WITNESS_REAL_APP_SCHEMA = 'versionless.witness-real-app-interactions.v4' as const;
4	export const WITNESS_REAL_APP_NAMES = [
5		'react-boilerplate',
6		'angular-phonecat',
7		'killedbygoogle',
8		'angular-realworld',
9		'papercups',
10		'react-hospitalrun',
11		'angular-factoriolab',
12		'angular-jira-clone',
13		/**
14		 * The LEGACY-NEXT static-export vertical, named by its pinned version rather
15		 * than by its repository. The corpus already carries `killedbygoogle` for the
16		 * retired derived-state-to-memo cell, and that name stays exactly where it
17		 * is: this is a different migration of a different revision against different
18		 * lanes, and giving it its own versioned name is what keeps the two proofs
19		 * from being read as one.
20		 */
21		'next-killedbygoogle-v3-0-0',
22		/**
23		 * The create-react-app 5 vertical, and the first in the corpus whose browser
24		 * proof runs against a SYNTHETIC dataset rather than the one its archive
25		 * ships. The application's data layer is 561 real contributors' personal
26		 * profiles; the standing ruling keeps every one of them out of the evidence,
27		 * and the application's own corpus-agnostic codegen is what makes the
28		 * substitution possible without touching a line of its source.
29		 */
30		'react-linkfree',
31		/**
32		 * The OLD-VITE-ORIGIN vertical, and the first in the corpus whose origin
33		 * bundler is Vite itself rather than a webpack-era toolchain: Vite 2.9.5 to
34		 * Vite 8.0.16, six majors apart. Its API surface is answered by a frozen
35		 * synthetic same-origin projection, because the application talks to a Go
36		 * backend that is out of the ingested cell entirely.
37		 */
38		'react-memos',
39		/**
40		 * The `.angular-cli.json` band vertical, and the corpus's longest lift:
41		 * Angular 5 to Angular 16.2, eleven majors. It is also the first application
42		 * here whose journey has to hand the page a file and read back a file the
43		 * page produced — it is a browser-only translation-file editor with no
44		 * backend at all — which is why the two opt-in mechanisms below exist.
45		 */
46		'angular-tiny-translator',
47		/**
48		 * The Angular 8 pre-Ivy ViewEngine vertical, and the first application here
49		 * whose production output ships a REAL service worker in both lanes: the era
50		 * build and the migrated build each emit `ngsw-worker.js`, `safety-worker.js`
51		 * and a generated manifest, and the application registers one on every
52		 * production load. Every other worker story in this corpus is an absence or a
53		 * refusal; this one is a registration that succeeds, which is why its schema
54		 * measures the settled state at three checkpoints per lane instead of
55		 * asserting a zero.
56		 *
57		 * It is also the first whose state lives in IndexedDB rather than in local
58		 * storage, and the second member of the closed drag list after jira-clone:
59		 * its task list reorders through the era's own dragula binding, a genuine
60		 * drag surface the vertical's journey now drives rather than refuses.
61		 */
62		'angular-super-productivity',
63	] as const;
64	/** Every named app must contribute two lanes observed twice each. */
65	export const WITNESS_REAL_APP_RUNS = WITNESS_REAL_APP_NAMES.length * 4;
66	
67	/**
68	 * The closed list of applications whose journeys are permitted to record a drag
69	 * gesture. Drag is not a gesture a journey may reach for because it is
70	 * available: it is only honest where the application has a genuine drag surface
71	 * whose settled result can be asserted exactly, so every other application in
72	 * the corpus continues to record drag as not-tested and fails the run if one
73	 * appears. Two applications earn it — jira-clone's board columns and
74	 * super-productivity's dragula-bound task list — and each admits its own
75	 * settled-order shape in its own schema.
76	 */
77	export const WITNESS_REAL_APP_DRAG_SURFACES = [
78		'angular-jira-clone',
79		'angular-super-productivity',
80	] as const;
81	
82	export type WitnessGesture = 'click' | 'type' | 'press' | 'hover' | 'scroll' | 'drag';
83	export type WitnessServiceWorkerTelemetry = {
84		state: 'ready';
85		registration: {
86			scriptPath: string | null;
87			scope: string | null;
88			installing: string | null;
89			waiting: string | null;
90			active: string | null;
91		};
92		controller: string | null;
93		cacheNames: string[];
94		cacheEntries: Array<{ name: string; paths: string[] }>;
95		workerEvents: Array<
96			| { kind: 'registration'; scopePath: string }
97			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
98			| {
99					kind: 'error';
100					message: string;
101					sourcePath: string;
102					lineNumber: number;
103					columnNumber: number;
104			  }
105		>;
106	};
107	export type WitnessOfflineEvidence =
108		| {
109				state: 'react-shell-rendered-state-reset';
110				shellRendered: true;
111				usernameReset: true;
112				repositoriesReset: true;
113				apiResponseCaching: 'not-claimed';
114				reduxPersistence: 'not-implemented';
115				priorResultPersistence: 'not-implemented';
116				harnessFulfillment: 'synthetic-github-route-online-only';
117				serviceWorkerEvidence: {
118					source: 'canonical-t060';
119					receiptPath: 'evidence/runs/react-boilerplate-v4-composed/t060-run.json';
120					canonicalDigest: '52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21';
121					newProof: false;
122				};
123				lifecycle: {
124					state: 'ready-online-reload-controlled-offline-reset';
125					ready: WitnessServiceWorkerTelemetry;
126					controlled: WitnessServiceWorkerTelemetry & { controller: 'activated' };
127					onlineStaticPaths: string[];
128					offlineServerRequests: 0;
129				};
130		  }
131		| { state: 'not-applicable' };
132	export type WitnessNextPrerenderPayloadEvidence =
133		| {
134				state: 'exact-lane-bound-next-prerender';
135				lane: 'baseline' | 'migrated';
136				buildId: string;
137				buildIdSha256: string;
138				retainedIndexSha256: string;
139				prerenderManifestSha256: string;
140				dataRoute: string;
141				sourcePath: string;
142				stagedPath: string;
143				payload: {
144					bytes: number;
145					sha256: string;
146					keys: ['__N_SSG', 'pageProps'];
147				};
148				response: {
149					method: 'GET';
150					pathname: string;
151					query: '';
152					destination: 'empty';
153					resolvedFile: string;
154					status: 200;
155					mime: 'application/json';
156					bytes: number;
157					sha256: string;
158				};
159		  }
160		| { state: 'not-applicable' };
161	/**
162	 * Exact, application-scoped accounting for console errors an application emits
163	 * on its own.
164	 *
165	 * A blanket "console errors are allowed" switch would mask regressions, so this
166	 * is deliberately not one: `expected` pins every message text and its exact
167	 * occurrence count, `observed` records what the browser actually reported, and
168	 * `outsideInventory` must stay empty — any error whose text is not already
169	 * pinned fails the run. Origins are normalized because the loopback port is
170	 * ephemeral; everything after the origin is real observed text.
171	 */
172	export type WitnessConsoleErrorInventoryEntry = { message: string; count: number };
173	export type WitnessConsoleErrorInventory = {
174		policy: 'exact-app-scoped-expected-console-errors';
175		originPlaceholder: '{production-static-origin}';
176		expected: WitnessConsoleErrorInventoryEntry[];
177		observed: WitnessConsoleErrorInventoryEntry[];
178		outsideInventory: [];
179		total: number;
180	};
181	
182	/**
183	 * Exact, application-scoped accounting for requests the browser itself failed,
184	 * held to the same discipline as the console-error inventory: every expected
185	 * failure is pinned by origin-relative path, method and reason with its exact
186	 * count, and any failure outside the pinned set fails the run. Paths are
187	 * origin-relative because the loopback port is ephemeral.
188	 */
189	export type WitnessFailedRequestInventoryEntry = {
190		method: string;
191		path: string;
192		/** The browser's own failure reason, or null when the driver reported none. */
193		reason: string | null;
194		count: number;
195	};
196	export type WitnessFailedRequestInventory = {
197		policy: 'exact-app-scoped-expected-failed-requests';
198		expected: WitnessFailedRequestInventoryEntry[];
199		observed: WitnessFailedRequestInventoryEntry[];
200		outsideInventory: [];
201		total: number;
202	};
203	
204	/**
205	 * The exact rule that admits a member of the cancelled-duplicate-fetch
206	 * category, carried in the receipt so a reader checks the rule rather than
207	 * trusting the label. It is stated once here and copied into every inventory,
208	 * so a receipt cannot quietly describe a weaker rule than the one the
209	 * mechanism enforced.
210	 */
211	export const WITNESS_CANCELLED_DUPLICATE_FETCH_RULE =
212		'A browser-cancelled fetch is admitted only when the same page also fetched the same origin-relative path with the same method successfully at least once during the same run. A cancelled fetch with no successful sibling is not admitted and fails the run as an ordinary failed request.' as const;
213	
214	/**
215	 * How a request outside the bounded loopback origin is written down.
216	 *
217	 * A seam the harness answers inside the browser context is still a request the
218	 * application made, and it belongs in the evidence. What does not belong is the
219	 * query string: for the analytics and error-reporting endpoints applications of
220	 * this era reach for, the query is exactly where the account identifier lives —
221	 * a measurement id, a DSN public key — and copying it into a published receipt
222	 * would publish a credential nobody asked to publish. So the recorded path for
223	 * a non-loopback request is query-free by construction: scheme, host and
224	 * pathname, and nothing after them. Nothing is lost that identifies the seam,
225	 * because the seam is the endpoint, not the account calling it.
226	 *
227	 * Same-origin loopback paths are untouched by this and stay exactly as the
228	 * browser requested them, query included: the loopback origin is the harness's
229	 * own, it mints no credentials, and its query strings are part of what a
230	 * production-static claim is about.
231	 */
232	export const WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE =
233		'A request outside the bounded loopback origin is recorded by scheme, host and pathname only. The query string is never recorded, because for these endpoints it carries the account identifier rather than the identity of the seam. Same-origin loopback paths are recorded exactly as requested, query included.' as const;
234	
235	/**
236	 * The extension of the cancelled-duplicate-fetch category to seams the harness
237	 * answers inside the browser context rather than over the network.
238	 *
239	 * The generic rule is unchanged and unweakened — a cancelled fetch is admitted
240	 * only when the same page fetched the same method and path successfully at
241	 * least once in the same run. What this states is that "successfully" means the
242	 * response the page actually received, whether it came from the bounded
243	 * loopback origin or from the harness answering a mocked seam in-context. A
244	 * navigation that aborts an in-flight report of a seam the same page already
245	 * reported to twice is the same race the category was built for, and it is
246	 * recorded as the category rather than pinned to a count the page's load timing
247	 * decides.
248	 */
249	export const WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE =
250		'The corroboration rule is applied unchanged to mocked non-loopback seams: the corroborating success is the 2xx response the page received, whether the bounded loopback origin or the in-context harness produced it. Members whose path is not loopback are pinned query-free, so no member can encode an account identifier.' as const;
251	
252	/**
253	 * One member of the cancelled-duplicate-fetch category, pinned by
254	 * recorded path, method and the browser's own cancellation reason.
255	 *
256	 * Deliberately no count. This category exists for one measured browser
257	 * behavior: a page fetches an asset, re-renders while that fetch is in flight,
258	 * starts an identical fetch, and the browser cancels one of the two. Which of
259	 * them the browser cancels, and how many times it happens in a given run, is
260	 * scheduling — pinning a count would pin a race. What is pinned instead is the
261	 * identity of the request that may be cancelled, and admission still requires
262	 * the corroboration below on every single instance.
263	 */
264	export type WitnessCancelledDuplicateFetchCategoryEntry = {
265		method: string;
266		path: string;
267		/** The browser's own cancellation reason, matched exactly. */
268		reason: string;
269	};
270	
271	/**
272	 * One admitted instance, recorded with the corroboration that admitted it, so
273	 * the receipt shows the evidence rather than the verdict. `cancelled` is the
274	 * number of times this exact fetch was cancelled in this run;
275	 * `corroboratingSuccesses` is the number of times the same page fetched the
276	 * same path and method successfully, and must be at least one.
277	 */
278	export type WitnessCancelledDuplicateFetchInstance = WitnessCancelledDuplicateFetchCategoryEntry & {
279		cancelled: number;
280		corroboratingSuccesses: number;
281		/** The distinct response statuses of those successful fetches, ascending. */
282		corroboratingStatuses: number[];
283	};
284	
285	/**
286	 * Accounting for the cancelled-duplicate-fetch category. This is a category,
287	 * not an allowance: it removes nothing from the evidence, it re-files a named
288	 * and corroborated browser behavior into its own inventory where every instance
289	 * is recorded individually. Every other failed request continues through the
290	 * exact {@link WitnessFailedRequestInventory} and still fails the run, and a
291	 * cancelled fetch that matches `category` but finds no successful sibling is
292	 * left in that inventory too — which is to say it fails.
293	 *
294	 * `absent` records category members this run never observed, because the whole
295	 * point of the category is that the behavior is intermittent: a run that did
296	 * not race is recorded as not having raced rather than silently indistinguishable
297	 * from one that did. `uncorroborated` must stay empty by construction.
298	 */
299	export type WitnessCancelledDuplicateFetchInventory = {
300		policy: 'corroborated-browser-cancelled-duplicate-fetch';
301		corroborationRule: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_RULE;
302		category: WitnessCancelledDuplicateFetchCategoryEntry[];
303		observed: WitnessCancelledDuplicateFetchInstance[];
304		absent: WitnessCancelledDuplicateFetchCategoryEntry[];
305		uncorroborated: [];
306		/** Cancelled fetches admitted by the category in this run, summed. */
307		admitted: number;
308		/**
309		 * Present exactly when the category declares a member outside the loopback
310		 * origin, and carrying the scope statement that governs those members. A run
311		 * whose category is entirely same-origin omits it, so an application that
312		 * never reached past loopback cannot be read as having claimed anything about
313		 * seams it does not have.
314		 */
315		nonLoopbackScope?: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE;
316	};
317	
318	/**
319	 * One non-loopback seam the application reaches for and the harness answers
320	 * inside the browser context, pinned by method and query-free recorded path.
321	 *
322	 * This is an inventory, not an allowance: the point of naming every seam is
323	 * that a request to an endpoint nobody declared fails the run rather than being
324	 * absorbed into a total. Nothing here is a successful non-loopback request —
325	 * none of these left the machine — which is why `successfulNonLoopback` stays
326	 * zero alongside it.
327	 */
328	export type WitnessMockedNonLoopbackSeamEntry = { method: string; path: string };
329	
330	/**
331	 * One declared seam as this run actually observed it. `requests` is recorded
332	 * rather than pinned, because how many times a page reports to an analytics or
333	 * error endpoint is load timing; the statuses are the answers the harness gave.
334	 */
335	export type WitnessMockedNonLoopbackSeamObservation = WitnessMockedNonLoopbackSeamEntry & {
336		requests: number;
337		/** The distinct statuses the harness answered with, ascending. */
338		statuses: number[];
339	};
340	
341	/**
342	 * Exact, application-scoped accounting for the seams an application reaches for
343	 * outside loopback, held to the same non-masking discipline as the console and
344	 * failed-request inventories: every declared member is either observed or
345	 * explicitly absent, and anything observed outside the declared membership is
346	 * reported by its own path and fails the run.
347	 */
348	export type WitnessMockedNonLoopbackSeamInventory = {
349		policy: 'exact-app-scoped-mocked-non-loopback-seams';
350		pathPolicy: typeof WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE;
351		category: WitnessMockedNonLoopbackSeamEntry[];
352		observed: WitnessMockedNonLoopbackSeamObservation[];
353		absent: WitnessMockedNonLoopbackSeamEntry[];
354		outsideInventory: [];
355		/** None of these left the machine; the harness answered every one in-context. */
356		successfulNonLoopback: 0;
357	};
358	
359	/**
360	 * Resolved appearance measured from the live page for a closed list of probes.
361	 *
362	 * A claim that two lanes render the same has to be measured on laid-out
363	 * elements, not inferred from the stylesheet bytes that were shipped — an
364	 * application whose migration replaced a narrow style entry point with an
365	 * aggregate ships different bytes on purpose, and the only honest way to say
366	 * the difference is invisible is to read what the browser resolved.
367	 */
368	export type WitnessRenderedStyleMeasurement = {
369		label: string;
370		selector: string;
371		width: number;
372		height: number;
373		properties: Record<string, string>;
374	};
375	export type WitnessRenderedStyleEvidence = {
376		state: 'measured-resolved-styles';
377		probes: WitnessRenderedStyleMeasurement[];
378	};
379	
380	/**
381	 * The exact rule that governs handing a file to a page, carried in the receipt
382	 * so a reader checks the rule rather than trusting the label.
383	 *
384	 * The mechanism is an opt-in and not a capability journeys may reach for: the
385	 * application declares the surface — the selector, and the fixture that is
386	 * loaded into it — and the harness loads exactly that. An application that
387	 * declares no file-input surface is run without the mechanism at all, so the
388	 * eleven verticals that never asked for it cannot have been changed by it.
389	 */
390	export const WITNESS_FILE_INPUT_LOAD_RULE =
391		'A file is handed to a page only through a surface the application itself declared, by selector and by fixture. The harness loads that fixture and no other, and records the bytes it handed over by file name, byte length and sha256. An application that declares no file-input surface has no way to load one.' as const;
392	
393	/**
394	 * The exact rule that governs reading back a file a page produced.
395	 *
396	 * Accepting downloads is a browser-context capability, and granting it to an
397	 * application that never claimed to produce one would mean a download could
398	 * succeed unobserved. So it is granted only where the application declares it,
399	 * and where it is granted every download is read back rather than counted:
400	 * suggested filename, byte length and sha256 of the bytes the browser wrote.
401	 */
402	export const WITNESS_DOWNLOAD_CAPTURE_RULE =
403		'A browser context accepts downloads only where the application declared that it produces them. Where it did, every download the page produced is read back by suggested filename, byte length and sha256 and ledgered individually. An application that declared none runs in a context that refuses downloads, so one it never claimed to produce cannot succeed unobserved.' as const;
404	
405	/** One file-input surface an application declared, by selector and fixture. */
406	export type WitnessFileInputSurfaceEntry = {
407		label: string;
408		selector: string;
409		/**
410		 * The fixture as declared: a repository-relative path, never a host-specific
411		 * absolute one, so the evidence names the file rather than the machine.
412		 */
413		fixturePath: string;
414	};
415	
416	/** One load as it happened, recorded from the exact bytes handed to the page. */
417	export type WitnessFileInputLoadEntry = WitnessFileInputSurfaceEntry & {
418		/** The name the page's own `File` object carries. */
419		fileName: string;
420		bytes: number;
421		sha256: string;
422	};
423	
424	/**
425	 * Accounting for the file-input mechanism, held to the same non-masking
426	 * discipline as the other inventories: every declared surface is either loaded
427	 * or explicitly unused, and `outsideDeclaration` must stay empty by
428	 * construction — a load through a surface nobody declared is impossible to
429	 * reach and fails the run if it is ever recorded.
430	 */
431	export type WitnessFileInputLoadInventory = {
432		policy: 'declared-file-input-surfaces-only';
433		rule: typeof WITNESS_FILE_INPUT_LOAD_RULE;
434		declared: WitnessFileInputSurfaceEntry[];
435		loaded: WitnessFileInputLoadEntry[];
436		unused: WitnessFileInputSurfaceEntry[];
437		outsideDeclaration: [];
438	};
439	
440	/** One download as the browser wrote it, read back rather than counted. */
441	export type WitnessCapturedDownloadEntry = {
442		suggestedFilename: string;
443		bytes: number;
444		sha256: string;
445	};
446	
447	/**
448	 * Accounting for the download-capture mechanism. `acceptDownloads` records the
449	 * browser-context capability this run was granted, so a reader can see that the
450	 * capability and the evidence came from the same declaration.
451	 */
452	export type WitnessDownloadCaptureInventory = {
453		policy: 'declared-download-surface-only';
454		rule: typeof WITNESS_DOWNLOAD_CAPTURE_RULE;
455		acceptDownloads: true;
456		captured: WitnessCapturedDownloadEntry[];
457	};
458	
459	/**
460	 * Measured journey facts that only one application's own surfaces can express —
461	 * the settled state of a board after a drag, the counts a filter narrowed to,
462	 * the text a tooltip rendered.
463	 *
464	 * The generic runner carries this without inspecting it, which is deliberate:
465	 * inventing a shared vocabulary for facts that are not shared would either
466	 * flatten them into something unfalsifiable or push one application's nouns
467	 * into everyone else's schema. The strictness is not lost, it moves — the
468	 * application's own receipt schema narrows this to an exact shape and checks
469	 * every field of it, and because the whole record participates in that
470	 * application's behavior digest, a lane that measured something different
471	 * cannot agree with its own pair.
472	 */
473	export type WitnessApplicationJourneyEvidence = Record<string, unknown>;
474	
475	/**
476	 * One observed service-worker-script event, stripped of the two fields that
477	 * cannot reproduce: the wall-clock timestamp and the run-global sequence
478	 * number, which counts every other asset the lane happens to load. What
479	 * remains — who observed it, in what phase, for which path, with what detail —
480	 * is the substance of the observation and is identical run to run.
481	 */
482	export type WitnessServiceWorkerRequestEvent = {
483		source: string;
484		phase: string;
485		urlPath: string | null;
486		detail: Record<string, boolean | number | string | null>;
487	};
488	/** The same event with the number of times it was observed, for exact accounting. */
489	export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
490		count: number;
491	};
492	
493	/**
494	 * One phased reading of a service worker that is genuinely running.
495	 *
496	 * The phases are the journey's own three moments — before it touches anything,
497	 * after it has, and after a reload that put the page back on the network — so a
498	 * worker that only looks installed at one of them cannot pass for one that
499	 * survived the journey.
500	 */
501	export type WitnessRealServiceWorkerCheckpoint = {
502		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
503		telemetry: WitnessServiceWorkerTelemetry;
504	};
505	
506	/**
507	 * A lane whose service-worker registration SUCCEEDS, which until now no shape in
508	 * this corpus could record.
509	 *
510	 * Every existing worker shape is a shape of absence: an application that never
511	 * asks, one whose registration the context refuses, one whose legacy build emits
512	 * a script it unregisters. Each of those asserts an empty settled state, so none
513	 * of them can carry a worker that installed, activated and took control — the
514	 * assertions that make them strong are exactly the assertions such a lane would
515	 * fail. This is the additive fourth member, and it is strong in the opposite
516	 * direction: the settled state is recorded rather than required to be empty, the
517	 * worker scripts the build shipped are read from the served tree before and
518	 * after the run and must be byte-identical, and the observer's own trace may not
519	 * be empty, because a browser that registered a worker recorded doing so.
520	 */
521	export type WitnessRealServiceWorkerEvidence = {
522		/** The script the application asked the browser to register. */
523		script: string;
524		checkpoints: WitnessRealServiceWorkerCheckpoint[];
525		/** The worker scripts the build emitted, read from the served tree either side of the run. */
526		outputFiles: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
527		workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
528	};
529	
530	/** The three phases, in the order a journey reaches them. */
531	export const WITNESS_REAL_SERVICE_WORKER_PHASES = [
532		'before-interactions',
533		'after-interactions',
534		'after-online-reload',
535	] as const;
536	
537	export type WitnessRealAppRun = {
538		app: (typeof WITNESS_REAL_APP_NAMES)[number];
539		framework: 'react' | 'angularjs' | 'next' | 'angular';
540		lane: 'baseline' | 'migrated';
541		pass: 1 | 2;
542		result: 'pass';
543		interactions: Array<{ kind: WitnessGesture; selector: string }>;
544		assertions: string[];
545		routes: string[];
546		trackedEvents: string[];
547		witnessRecord: {
548			interactions: Array<{ kind: WitnessGesture; selector: string }>;
549			navigationPaths: string[];
550			trackedEventCounts: Record<string, number>;
551			consoleErrors: number;
552			pageErrors: number;
553			/**
554			 * Requests the browser failed, excluding the ones admitted by this run's
555			 * cancelled-duplicate-fetch category, which are recorded instance by
556			 * instance in {@link WitnessRealAppRun.cancelledDuplicateFetches}. A run
557			 * that declares no such category — every application here but the ones
558			 * that measured the behavior — has nothing to exclude, so this stays the
559			 * total number of browser-failed requests it has always been.
560			 */
561			failedRequests: number;
562		};
563		cleanPage: true;
564		offlineEvidence: WitnessOfflineEvidence;
565		servedStatic: {
566			transport: 'isolated-bounded-loopback-production-static';
567			documentFallback: 'index-only';
568			missingAssets: '404';
569			traversal: 'rejected';
570			inventory: { files: number; beforeSha256: string; afterSha256: string };
571			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
572			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
573			byteIdentical: true;
574			hmrControls: false;
575			legacyMainPrecache:
576				| {
577						state: 'exact-completed';
578						responses: Array<{
579							method: 'GET';
580							pathname: string;
581							query: '?__uncache=versionless-deterministic';
582							destination: 'empty';
583							resolvedFile: string;
584							status: 200;
585							mime: string;
586							bytes: number;
587							sha256: string;
588							urlPath: string;
589							source: 'production-static-origin';
590						}>;
591				  }
592				| { state: 'not-applicable' };
593			phonecatOrdering:
594				| {
595						state: 'data-derived-full-order';
596						datasetSha256: string;
597						orderSha256: string;
598						rows: 20;
599						comparator: 'stable-lowercase-utf16-source-order-ties';
600				  }
601				| { state: 'not-applicable' };
602			phonecatImageTransition:
603				| {
604						state: 'data-derived-visible-transition';
605						detailSha256: string;
606						defaultImage: string;
607						nonDefaultImage: string;
608						hover: 'genuine-thumbnail-mouseover';
609						transition: 'genuine-ng-click';
610						heroVisibility: 'genuine-hover';
611				  }
612				| { state: 'not-applicable' };
613			nextPrerenderPayload?: WitnessNextPrerenderPayloadEvidence;
614		};
615		observerFinalization: {
616			state: 'target-closed';
617			detach: 'owned-detach-complete';
618			pageClose: 'owned-page-close-complete';
619			workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
620		};
621		semanticDigest: string;
622		successfulNonLoopback: 0;
623		consoleErrorInventory?: WitnessConsoleErrorInventory;
624		failedRequestInventory?: WitnessFailedRequestInventory;
625		cancelledDuplicateFetches?: WitnessCancelledDuplicateFetchInventory;
626		mockedNonLoopbackSeams?: WitnessMockedNonLoopbackSeamInventory;
627		/**
628		 * Present exactly when the application declared a file-input surface. Its
629		 * absence is the evidence that this run's page was never handed a file.
630		 */
631		fileInputLoads?: WitnessFileInputLoadInventory;
632		/**
633		 * Present exactly when the application declared that it produces downloads.
634		 * Its absence is the evidence that this run's browser context refused them.
635		 */
636		downloadCaptures?: WitnessDownloadCaptureInventory;
637		renderedStyles?: WitnessRenderedStyleEvidence;
638		applicationJourney?: WitnessApplicationJourneyEvidence;
639		scrollSurface?: WitnessScrollSurface;
640		scrollAbsence?: WitnessMeasuredScrollAbsence;
641	};
642	
643	/**
644	 * Measured scroll evidence for one route that genuinely overflows the stated
645	 * viewport. The document extents are read from the live page, and the scroll
646	 * itself is a real wheel gesture the browser driver confirms moved the
647	 * viewport — the boolean is an observation, not a claim substituted for one.
648	 */
649	export type WitnessScrollSurface = {
650		state: 'measured-genuine-viewport-scroll';
651		route: string;
652		viewport: { width: number; height: number };
653		scrollHeight: number;
654		clientHeight: number;
655		wheelDeltaY: number;
656		scrolledFromTop: true;
657		scrolled: true;
658	};
659	
660	/**
661	 * The measured counterpart of {@link WitnessScrollSurface}: evidence that a
662	 * journey looked for a scroll surface and did not find one.
663	 *
664	 * An application that pins its document to the viewport and scrolls its own
665	 * inner panels instead has no scrollable document to gesture at, and inventing
666	 * one would be a false claim. So the same generic measurement that backs a
667	 * scroll claim is taken at every visited route and recorded here instead:
668	 * `scrollHeight` never exceeds `clientHeight`, which is why no scroll coverage
669	 * is claimed. Routes are recorded individually rather than summarized, so a
670	 * route that starts overflowing later cannot hide inside a total.
671	 */
672	export type WitnessMeasuredScrollAbsence = {
673		state: 'measured-no-overflowing-document';
674		viewport: { width: number; height: number };
675		routes: Array<{ route: string; scrollHeight: number; clientHeight: number }>;
676		/** How the application keeps the document from overflowing, observed rather than assumed. */
677		documentOverflow: string;
678		claimed: false;
679	};
680	
681	export type WitnessMutationProof = {
682		app: 'react-boilerplate' | 'angular-realworld';
683		failure: 'witness-semantic-assertion';
684		intendedFailure: true;
685		restoredByteIdentically: true;
686	};
687	
688	export type WitnessRealAppReceipt = {
689		schemaVersion: typeof WITNESS_REAL_APP_SCHEMA;
690		result: 'pass';
691		provenance: Record<string, unknown>;
692		canonicalReceipts: Array<{
693			app: string;
694			path: string;
695			sha256: string;
696			canonicalDigest: string;
697		}>;
698		runs: WitnessRealAppRun[];
699		mutations: WitnessMutationProof[];
700		killedByGoogleInventory: {
701			archiveSha256: string;
702			mirrorFiles: number;
703			sourceFiles: Record<'baseline' | 'migrated', number>;
704			buildFiles: Record<'baseline' | 'migrated', number>;
705			transformEdits: 3;
706		};
707		locality: { mode: 'offline'; successfulNonLoopback: 0; osWideIsolation: false };
708		nonclaims: string[];
709		integrity: { algorithm: 'sha256'; canonicalDigest: string };
710	};
711	
712	function record(value: unknown, label: string): Record<string, unknown> {
713		if (value === null || typeof value !== 'object' || Array.isArray(value))
714			throw new Error(`Witness real-app ${label} must be an object`);
715		return value as Record<string, unknown>;
716	}
717	
718	function sha256Digest(value: unknown): value is string {
719		return typeof value === 'string' && value.length === 64;
720	}
721	
722	function sortedUniqueStrings(values: unknown): values is string[] {
723		return (
724			Array.isArray(values) &&
725			values.every((value) => typeof value === 'string') &&
726			new Set(values).size === values.length &&
727			values.join('\n') === [...values].sort().join('\n')
728		);
729	}
730	
731	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
732		const telemetry = value as WitnessServiceWorkerTelemetry;
733		return (
734			telemetry?.state === 'ready' &&
735			telemetry.registration?.scriptPath === '/sw.js' &&
736			telemetry.registration.scope === '/' &&
737			telemetry.registration.active === 'activated' &&
738			(telemetry.controller === 'activated' || telemetry.controller === null) &&
739			sortedUniqueStrings(telemetry.cacheNames) &&
740			telemetry.cacheNames.length === 1 &&
741			Array.isArray(telemetry.cacheEntries) &&
742			telemetry.cacheEntries.length === 1 &&
743			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
744			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
745			telemetry.cacheEntries[0].paths.length > 0 &&
746			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
747			Array.isArray(telemetry.workerEvents)
748		);
749	}
750	
751	export function witnessRealAppDigest(receipt: WitnessRealAppReceipt): string {
752		const copy = structuredClone(receipt);
753		copy.integrity.canonicalDigest = '';
754		return sha256(canonicalize(copy));
755	}
756	
757	export function parseWitnessRealAppReceipt(value: unknown): WitnessRealAppReceipt {
758		const receipt = record(value, 'receipt') as WitnessRealAppReceipt;
759		if (
760			receipt.schemaVersion !== WITNESS_REAL_APP_SCHEMA ||
761			receipt.result !== 'pass' ||
762			!Array.isArray(receipt.runs) ||
763			receipt.runs.length !== WITNESS_REAL_APP_RUNS ||
764			!Array.isArray(receipt.canonicalReceipts) ||
765			receipt.canonicalReceipts.length !== WITNESS_REAL_APP_NAMES.length
766		)
767			throw new Error('Witness real-app receipt cardinality differs');
768		const expected = new Set<string>();
769		for (const app of WITNESS_REAL_APP_NAMES)
770			for (const lane of ['baseline', 'migrated'])
771				for (const pass of [1, 2]) expected.add(`${app}:${lane}:${pass}`);
772		const gestures = new Set<WitnessGesture>();
773		const semanticPasses = new Map<string, string>();
774		for (const run of receipt.runs) {
775			const key = `${run.app}:${run.lane}:${run.pass}`;
776			const served = run.servedStatic;
777			const servedStaticDiffers =
778				served?.transport !== 'isolated-bounded-loopback-production-static' ||
779				served.documentFallback !== 'index-only' ||
780				served.missingAssets !== '404' ||
781				served.traversal !== 'rejected' ||
782				!Number.isInteger(served.inventory?.files) ||
783				served.inventory.files < 1 ||
784				!sha256Digest(served.inventory.beforeSha256) ||
785				served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
786				served.application?.path !== 'index.html' ||
787				!sha256Digest(served.application.beforeSha256) ||
788				served.application.beforeSha256 !== served.application.afterSha256 ||
789				!Array.isArray(served.serviceWorkers) ||
790				served.serviceWorkers.some(
791					(serviceWorker) =>
792						serviceWorker.path !== 'sw.js' ||
793						!sha256Digest(serviceWorker.beforeSha256) ||
794						serviceWorker.beforeSha256 !== serviceWorker.afterSha256,
795				) ||
796				(run.app === 'react-boilerplate'
797					? served.serviceWorkers.length !== 1
798					: served.serviceWorkers.length !== 0) ||
799				served.byteIdentical !== true ||
800				served.hmrControls !== false;
801			const expectedLegacyMain = [
802				['/favicon.ico', 'favicon.ico', 'image/x-icon'],
803				[
804					'/2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
805					'2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
806					'image/jpeg',
807				],
808				[
809					'/runtime.bfb7866e5bd316b6a048.js',
810					'runtime.bfb7866e5bd316b6a048.js',
811					'text/javascript',
812				],
813				['/', 'index.html', 'text/html'],
814			] as const;
815			const legacyMainPrecacheDiffers =
816				run.app === 'react-boilerplate' && run.lane === 'baseline'
817					? served.legacyMainPrecache?.state !== 'exact-completed' ||
818						served.legacyMainPrecache.responses.length !== expectedLegacyMain.length ||
819						served.legacyMainPrecache.responses.some((response, index) => {
820							const expectedResponse = expectedLegacyMain[index];
821							return (
822								expectedResponse === undefined ||
823								response.method !== 'GET' ||
824								response.pathname !== expectedResponse[0] ||
825								response.query !== '?__uncache=versionless-deterministic' ||
826								response.destination !== 'empty' ||
827								response.resolvedFile !== expectedResponse[1] ||
828								response.status !== 200 ||
829								response.mime !== expectedResponse[2] ||
830								!Number.isInteger(response.bytes) ||
831								response.bytes < 1 ||
832								!sha256Digest(response.sha256) ||
833								response.urlPath !== `${response.pathname}${response.query}` ||
834								response.source !== 'production-static-origin'
835							);
836						})
837					: served.legacyMainPrecache?.state !== 'not-applicable';
838			const phonecatOrderingDiffers =
839				run.app === 'angular-phonecat'
840					? served.phonecatOrdering?.state !== 'data-derived-full-order' ||
841						!sha256Digest(served.phonecatOrdering.datasetSha256) ||
842						!sha256Digest(served.phonecatOrdering.orderSha256) ||
843						served.phonecatOrdering.rows !== 20 ||
844						served.phonecatOrdering.comparator !==
845							'stable-lowercase-utf16-source-order-ties'
846					: served.phonecatOrdering?.state !== 'not-applicable';
847			const phonecatImageTransitionDiffers =
848				run.app === 'angular-phonecat'
849					? served.phonecatImageTransition?.state !== 'data-derived-visible-transition' ||
850						!sha256Digest(served.phonecatImageTransition.detailSha256) ||
851						!served.phonecatImageTransition.defaultImage.startsWith('img/phones/') ||
852						!served.phonecatImageTransition.nonDefaultImage.startsWith('img/phones/') ||
853						served.phonecatImageTransition.defaultImage ===
854							served.phonecatImageTransition.nonDefaultImage ||
855						served.phonecatImageTransition.hover !== 'genuine-thumbnail-mouseover' ||
856						served.phonecatImageTransition.transition !== 'genuine-ng-click' ||
857						served.phonecatImageTransition.heroVisibility !== 'genuine-hover'
858					: served.phonecatImageTransition?.state !== 'not-applicable';
859			const observerFinalizationDiffers =
860				run.observerFinalization?.state !== 'target-closed' ||
861				run.observerFinalization.detach !== 'owned-detach-complete' ||
862				run.observerFinalization.pageClose !== 'owned-page-close-complete' ||
863				!Array.isArray(run.observerFinalization.workerEvents);
864			const lifecycle =
865				run.offlineEvidence.state === 'react-shell-rendered-state-reset'
866					? run.offlineEvidence.lifecycle
867					: undefined;
868			const expectedCacheName =
869				run.lane === 'baseline'
870					? 'webpack-offline:versionless-deterministic'
871					: 'versionless-react-vite8-553cd1cc611a0851b1978bbc041ef2f8c7b9fbbd3fdd9bb68274f29364987cdc';
872			const lifecycleDiffers =
873				run.app === 'react-boilerplate'
874					? lifecycle?.state !== 'ready-online-reload-controlled-offline-reset' ||
875						!validServiceWorkerTelemetry(lifecycle.ready) ||
876						!validServiceWorkerTelemetry(lifecycle.controlled) ||
877						lifecycle.controlled.controller !== 'activated' ||
878						lifecycle.ready.cacheNames[0] !== expectedCacheName ||
879						canonicalize(lifecycle.ready.cacheEntries) !==
880							canonicalize(lifecycle.controlled.cacheEntries) ||
881						!sortedUniqueStrings(lifecycle.onlineStaticPaths) ||
882						!lifecycle.onlineStaticPaths.includes('/sw.js') ||
883						lifecycle.ready.cacheEntries[0]!.paths.some(
884							(path) =>
885								path !== '/__offline_webpack__data' &&
886								!lifecycle.onlineStaticPaths.includes(path),
887						) ||
888						lifecycle.offlineServerRequests !== 0
889					: lifecycle !== undefined;
890			if (
891				run.interactions.some((interaction) => interaction.kind === 'drag') &&
892				!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(run.app)
893			)
894				throw new Error('Witness real-app drag must remain not-tested');
895			if (
896				!expected.delete(key) ||
897				run.result !== 'pass' ||
898				run.successfulNonLoopback !== 0 ||
899				!Array.isArray(run.interactions) ||
900				run.interactions.length === 0 ||
901				!Array.isArray(run.assertions) ||
902				run.assertions.length === 0 ||
903				servedStaticDiffers ||
904				legacyMainPrecacheDiffers ||
905				phonecatOrderingDiffers ||
906				phonecatImageTransitionDiffers ||
907				observerFinalizationDiffers ||
908				lifecycleDiffers ||
909				run.cleanPage !== true ||
910				(run.app === 'react-boilerplate'
911					? run.offlineEvidence?.state !== 'react-shell-rendered-state-reset' ||
912						run.offlineEvidence.shellRendered !== true ||
913						run.offlineEvidence.usernameReset !== true ||
914						run.offlineEvidence.repositoriesReset !== true ||
915						run.offlineEvidence.apiResponseCaching !== 'not-claimed' ||
916						run.offlineEvidence.reduxPersistence !== 'not-implemented' ||
917						run.offlineEvidence.priorResultPersistence !== 'not-implemented' ||
918						run.offlineEvidence.harnessFulfillment !==
919							'synthetic-github-route-online-only' ||
920						run.offlineEvidence.serviceWorkerEvidence?.source !== 'canonical-t060' ||
921						run.offlineEvidence.serviceWorkerEvidence.receiptPath !==
922							'evidence/runs/react-boilerplate-v4-composed/t060-run.json' ||
923						run.offlineEvidence.serviceWorkerEvidence.canonicalDigest !==
924							'52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21' ||
925						run.offlineEvidence.serviceWorkerEvidence.newProof !== false
926					: run.offlineEvidence?.state !== 'not-applicable') ||
927				run.semanticDigest !==
928					sha256(
929						canonicalize({
930							app: run.app,
931							framework: run.framework,
932							lane: run.lane,
933							interactions: run.interactions,
934							assertions: run.assertions,
935							routes: run.routes,
936							trackedEvents: run.trackedEvents,
937							witnessRecord: run.witnessRecord,
938							cleanPage: run.cleanPage,
939							offlineEvidence: run.offlineEvidence,
940							servedStatic: run.servedStatic,
941							observerFinalization: run.observerFinalization,
942							successfulNonLoopback: run.successfulNonLoopback,
943						}),
944					)
945			)
946				throw new Error(`Witness real-app run differs: ${key}`);
947			const pair = `${run.app}:${run.lane}`;
948			const prior = semanticPasses.get(pair);
949			if (prior !== undefined && prior !== run.semanticDigest)
950				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
951			semanticPasses.set(pair, run.semanticDigest);
952			for (const interaction of run.interactions) {
953				gestures.add(interaction.kind);
954			}
955		}
956		if (
957			expected.size !== 0 ||
958			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
959		)
960			throw new Error('Witness real-app interaction coverage differs');
961		if (
962			receipt.mutations?.length !== 2 ||
963			receipt.mutations.some(
964				(mutation) =>
965					mutation.failure !== 'witness-semantic-assertion' ||
966					mutation.intendedFailure !== true ||
967					mutation.restoredByteIdentically !== true,
968			) ||
969			!receipt.mutations.some((mutation) => mutation.app === 'react-boilerplate') ||
970			!receipt.mutations.some((mutation) => mutation.app === 'angular-realworld') ||
971			receipt.killedByGoogleInventory?.transformEdits !== 3 ||
972			receipt.locality?.mode !== 'offline' ||
973			receipt.locality?.successfulNonLoopback !== 0 ||
974			receipt.locality?.osWideIsolation !== false ||
975			!receipt.nonclaims?.some((claim) => claim.includes('Drag is tested only')) ||
976			receipt.integrity?.algorithm !== 'sha256' ||
977			receipt.integrity.canonicalDigest !== witnessRealAppDigest(receipt)
978		)
979			throw new Error('Witness real-app receipt integrity or nonclaims differ');
980		return receipt;
981	}
