330		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
331		const withoutBehavior = { ...raw } as Record<string, unknown>;
332		delete withoutBehavior.behaviorDigest;
333		return sha256(canonicalize(withoutBehavior));
334	}
335	
336	/**
337	 * Deterministic tracked-event floor.
338	 *
339	 * The typed, clicked, changed and keyed counts are exact and identical in every
340	 * lane and pass, so they are pinned. Incidental `mouseover` events depend on the
341	 * pointer path the host takes between the genuine hovers, so the count is
342	 * bounded from below by those hovers instead of being pinned to an unstable
343	 * number. The bound is checked, not erased.
344	 */
345	export const WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS = Object.freeze({
346		change: 2,
347		click: 12,
348		input: 16,
349		keydown: 16,
350		mouseoverAtLeast: 3,
351	});
352	
353	function trackedEventProjection(run: WitnessRealAppRun): Record<string, unknown> {
354		const counts = run.witnessRecord.trackedEventCounts;
355		const mouseover = counts.mouseover ?? 0;
356		if (
357			counts.change !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.change ||
358			counts.click !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.click ||
359			counts.input !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.input ||
360			counts.keydown !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.keydown ||
361			mouseover < WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.mouseoverAtLeast ||
362			Object.keys(counts).sort().join(',') !== 'change,click,input,keydown,mouseover'
363		)
364			throw new Error('React HospitalRun tracked browser events differ');
365		return {
366			change: counts.change,
367			click: counts.click,
368			input: counts.input,
369			keydown: counts.keydown,
370			mouseover: `at-least-${WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.mouseoverAtLeast}-genuine-hovers`,
371		};
372	}
373	
374	/**
375	 * Lane-independent behavior projection.
376	 *
377	 * Production bytes are lane-specific by construction, so the byte inventory
378	 * stays in the run record and out of this digest. The console-error inventory
379	 * is lane-specific on purpose — it is the recorded migration difference — so
380	 * the digest carries its shape and total rather than its lane-bound text, and
381	 * the text itself is verified exactly against the pinned inventory elsewhere.
382	 */
383	export function witnessReactHospitalrunBehaviorDigest(
384		run: WitnessReactHospitalrunRun | WitnessRealAppRun,
385	): string {
386		const blocked = (run as WitnessReactHospitalrunRun).blockedServiceWorkerRuntime;
387		const inventory = run.consoleErrorInventory;
388		return sha256(
389			canonicalize({
390				app: run.app,
391				framework: run.framework,
392				interactions: run.interactions,
393				assertions: run.assertions,
394				routes: run.routes,
395				trackedEvents: run.trackedEvents,
396				witnessRecord: {
397					...run.witnessRecord,
398					trackedEventCounts: trackedEventProjection(run),
399				},
400				cleanPage: run.cleanPage,
401				offlineEvidence: run.offlineEvidence,
402				servedStaticPolicy: {
403					transport: run.servedStatic.transport,
404					documentFallback: run.servedStatic.documentFallback,
405					missingAssets: run.servedStatic.missingAssets,
406					traversal: run.servedStatic.traversal,
407					byteIdentical: run.servedStatic.byteIdentical,
408					hmrControls: run.servedStatic.hmrControls,
409				},
410				blockedServiceWorkerRuntime: {
411					registration: blocked?.registration,
412					checkpoints: blocked?.checkpoints,
413					workerEvents: blocked?.workerEvents,
414					// The worker-script trace is lane-specific on purpose — a served
415					// 200 against a 404 is the recorded migration difference — so the
416					// parity digest carries only what both lanes must share: the same
417					// number of registration attempts, all refused, none surviving.
418					// The lane-specific trace is verified exactly against its pinned
419					// tally elsewhere.
420					registrationAttempts: (blocked?.requests ?? []).filter(
421						(event) => event.source === 'browser' && event.phase === 'request',
422					).length,
423					abortedWorkerScriptFetches: (blocked?.requests ?? []).filter(
424						(event) => event.phase === 'failure',
425					).length,
426				},
427				consoleErrorPolicy: {
428					policy: inventory?.policy,
429					outsideInventory: inventory?.outsideInventory,
430					total: inventory?.total,
431				},
432				// Identical in both lanes, so the whole inventory is lane-independent
433				// and participates in the parity digest rather than only its shape.
434				failedRequestInventory: run.failedRequestInventory,
435				scrollSurface: run.scrollSurface,
436				successfulNonLoopback: run.successfulNonLoopback,
437			}),
438		);
439	}
440	
441	export function witnessReactHospitalrunDigest(receipt: WitnessReactHospitalrunReceipt): string {
442		const copy = structuredClone(receipt);
443		copy.integrity.canonicalDigest = '';
444		return sha256(canonicalize(copy));
445	}
446	
447	/**
448	 * The lane-specific worker-script trace, verified exactly. `lane` is null for
449	 * the receipt-level summary, which carries only the lane-independent parts.
450	 */
451	function assertServiceWorkerRequests(
452		blocked: WitnessReactHospitalrunBlockedServiceWorker,
453		lane: 'baseline' | 'migrated' | null,
454		label: string,
455	): void {
456		if (!Array.isArray(blocked.requests) || !Array.isArray(blocked.requestTally))
457			throw new Error(`React HospitalRun worker-script trace is absent: ${label}`);
458		const attempts = blocked.requests.filter(
459			(event) => event.source === 'browser' && event.phase === 'request',
460		).length;
461		if (attempts !== WITNESS_REACT_HOSPITALRUN_REGISTRATION_ATTEMPTS)
462			throw new Error(`React HospitalRun registration attempts differ: ${label}`);
463		if (lane === null) return;
464		const pinned = [...WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_REQUESTS[lane]];
465		const observed = new Map<string, number>();
466		for (const event of blocked.requests) {
467			const key = canonicalize({
468				source: event.source,
469				phase: event.phase,
470				urlPath: event.urlPath,
471				detail: event.detail,
472			});
473			observed.set(key, (observed.get(key) ?? 0) + 1);
474		}
475		const expected = new Map(
476			pinned.map((entry) => [
477				canonicalize({
478					source: entry.source,
479					phase: entry.phase,
480					urlPath: entry.urlPath,
481					detail: entry.detail,
482				}),
483				entry.count,
484			]),
485		);
486		if (
487			observed.size !== expected.size ||
488			[...expected].some(([key, count]) => observed.get(key) !== count) ||
489			blocked.requests.length !== pinned.reduce((sum, entry) => sum + entry.count, 0) ||
490			!exact(
491				[...blocked.requestTally].sort((left, right) =>
492					compareUtf16CodeUnits(canonicalize(left), canonicalize(right)),
493				),
494				[...pinned].sort((left, right) =>
495					compareUtf16CodeUnits(canonicalize(left), canonicalize(right)),
496				),
497			)
498		)
499			throw new Error(`React HospitalRun worker-script trace differs: ${label}`);
500	}
501	
502	function assertBlockedServiceWorker(
503		blocked: WitnessReactHospitalrunBlockedServiceWorker | undefined,
504		lane: 'baseline' | 'migrated' | null,
505		label: string,
506	): void {
507		if (
508			blocked === undefined ||
509			blocked.registration !== 'application-register-refused-by-context' ||
510			!Array.isArray(blocked.emittedOutputFiles) ||
511			!exact(blocked.workerEvents, []) ||
512			!Array.isArray(blocked.checkpoints) ||
513			blocked.checkpoints.length !== 3 ||
514			canonicalize(blocked.checkpoints.map((checkpoint) => checkpoint.phase)) !==
515				canonicalize(['before-interactions', 'after-interactions', 'after-online-reload']) ||
516			blocked.checkpoints.some(
517				(checkpoint) =>
518					checkpoint.state !== 'timeout' ||
519					checkpoint.registrations !== 0 ||
520					checkpoint.controller !== null ||
521					checkpoint.cacheNames.length !== 0 ||
522					checkpoint.workerEvents.length !== 0,
523			)
524		)
525			throw new Error(`React HospitalRun blocked service-worker evidence differs: ${label}`);
526		assertServiceWorkerRequests(blocked, lane, label);
527	}
528	
529	function assertConsoleErrorInventory(
530		inventory: WitnessConsoleErrorInventory | undefined,
531		lane: 'baseline' | 'migrated',
532		label: string,
533	): void {
534		const pinned = [...WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS[lane]].map((entry) => ({
535			message: entry.message,
536			count: entry.count,
537		}));
538		if (
539			inventory === undefined ||
540			inventory.policy !== 'exact-app-scoped-expected-console-errors' ||
541			inventory.originPlaceholder !== '{production-static-origin}' ||
542			!exact(inventory.outsideInventory, []) ||
543			!exact(inventory.expected, pinned) ||
544			!exact(inventory.observed, pinned) ||
545			inventory.total !== pinned.reduce((sum, entry) => sum + entry.count, 0)
546		)
547			throw new Error(`React HospitalRun console-error inventory differs: ${label}`);
548	}
549	
550	function assertFailedRequestInventory(
551		inventory: WitnessFailedRequestInventory | undefined,
552		lane: 'baseline' | 'migrated',
553		label: string,
554	): void {
555		const pinned = [...WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS[lane]].map((entry) => ({
556			method: entry.method,
557			path: entry.path,
558			reason: entry.reason,
559			count: entry.count,
560		}));
561		if (
562			inventory === undefined ||
563			inventory.policy !== 'exact-app-scoped-expected-failed-requests' ||
564			!exact(inventory.outsideInventory, []) ||
565			!exact(inventory.expected, pinned) ||
566			!exact(inventory.observed, pinned) ||
567			inventory.total !== pinned.reduce((sum, entry) => sum + entry.count, 0)
568		)
569			throw new Error(`React HospitalRun failed-request inventory differs: ${label}`);
570	}
571	
572	function assertScrollSurface(surface: WitnessScrollSurface | undefined, label: string): void {
573		if (
574			surface === undefined ||
575			surface.state !== 'measured-genuine-viewport-scroll' ||
576			surface.route !== '/appointments' ||
577			surface.viewport.width !== 1280 ||
578			surface.viewport.height !== 720 ||
579			surface.clientHeight !== 720 ||
580			surface.scrollHeight <= surface.clientHeight ||
581			surface.wheelDeltaY <= 0 ||
582			surface.scrolledFromTop !== true ||
583			surface.scrolled !== true
584		)
585			throw new Error(`React HospitalRun scroll surface differs: ${label}`);
586	}
587	
588	export function parseWitnessReactHospitalrunReceipt(
589		value: unknown,
590	): WitnessReactHospitalrunReceipt {
591		if (value === null || typeof value !== 'object' || Array.isArray(value))
592			throw new Error('React HospitalRun Witness receipt must be an object');
593		const receipt = value as WitnessReactHospitalrunReceipt;
594		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
595		const behaviors = new Set<string>();
596		if (
597			receipt.schemaVersion !== WITNESS_REACT_HOSPITALRUN_SCHEMA ||
598			receipt.result !== 'pass' ||
599			receipt.fixture !== REACT_HOSPITALRUN_FIXTURE ||
600			!exact(receipt.source, REACT_HOSPITALRUN_SOURCE) ||
601			receipt.canonicalReceipt?.path !== REACT_HOSPITALRUN_RECEIPT_PATH ||
602			receipt.canonicalReceipt.canonicalDigest !== REACT_HOSPITALRUN_CANONICAL_DIGEST ||
603			receipt.canonicalReceipt.sha256 !== REACT_HOSPITALRUN_RECEIPT_SHA256 ||
604			!Array.isArray(receipt.runs) ||
605			receipt.runs.length !== 4
606		)
607			throw new Error('React HospitalRun Witness binding differs');
608		for (const run of receipt.runs) {
609			const key = `${run.lane}:${run.pass}`;
610			if (
611				!expectedRuns.delete(key) ||
612				run.app !== 'react-hospitalrun' ||
613				run.framework !== 'react' ||
614				run.result !== 'pass' ||
615				run.cleanPage !== true ||
616				run.successfulNonLoopback !== 0 ||
617				run.witnessRecord.pageErrors !== 0 ||
618				run.witnessRecord.failedRequests !== run.failedRequestInventory?.total ||
619				run.witnessRecord.consoleErrors !== run.consoleErrorInventory?.total ||
620				run.offlineEvidence.state !== 'not-applicable' ||
621				run.observerFinalization.workerEvents.length !== 0 ||
622				run.semanticDigest !== witnessReactHospitalrunRawDigest(run) ||
623				run.behaviorDigest !== witnessReactHospitalrunBehaviorDigest(run) ||
624				!exact(run.routes, WITNESS_REACT_HOSPITALRUN_ROUTES)
625			)
626				throw new Error(`React HospitalRun Witness run differs: ${key}`);
627			assertBlockedServiceWorker(run.blockedServiceWorkerRuntime, run.lane, key);
628			assertConsoleErrorInventory(run.consoleErrorInventory, run.lane, key);
629			assertFailedRequestInventory(run.failedRequestInventory, run.lane, key);
630			assertScrollSurface(run.scrollSurface, key);
631			behaviors.add(run.behaviorDigest);
632		}
633		assertBlockedServiceWorker(receipt.blockedServiceWorker, null, 'receipt');
634		assertScrollSurface(receipt.scrollSurface, 'receipt');
635		if (
636			expectedRuns.size !== 0 ||
637			behaviors.size !== 1 ||
638			!exact(receipt.consoleErrors, WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS) ||
639			!exact(receipt.failedRequests, WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS) ||
640			!exact(
641				receipt.serviceWorkerDifference,
642				WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
643			) ||
644			!exact(receipt.persistence, {
645				store: 'browser-local-pouchdb',
646				stubbed: false,
647				survivesOnlineReload: true,
648			}) ||
649			receipt.mutation?.intendedFailure !== true ||
650			receipt.mutation.failure !== 'witness-semantic-assertion' ||
651			receipt.mutation.lane !== 'migrated' ||
652			receipt.mutation.restoredByteIdentically !== true ||
653			receipt.mutation.restoredRun !== 'pass' ||
654			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
655			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
656			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
657			!exact(receipt.readiness, {
658				reactLineage: { ready: 1, total: 4, counted: false },
659				overall: { ready: 3, total: 12 },
660			}) ||
661			receipt.locality?.mode !== 'offline' ||
662			receipt.locality.successfulNonLoopback !== 0 ||
663			receipt.locality.osWideIsolation !== false ||
664			!Array.isArray(receipt.nonclaims) ||
665			receipt.nonclaims.length === 0 ||
666			receipt.integrity?.algorithm !== 'sha256' ||
667			receipt.integrity.canonicalDigest !== witnessReactHospitalrunDigest(receipt)
668		)
669			throw new Error('React HospitalRun Witness integrity differs');
670		return receipt;
671	}
672	
673	function uniqueSorted(values: readonly string[]): string[] {
674		return [...new Set(values)].sort();
675	}
676	
677	export function renderWitnessReactHospitalrunReceipt(
678		receipt: WitnessReactHospitalrunReceipt,
679	): string {
680		const emitted = receipt.runs.flatMap((run) =>
681			run.blockedServiceWorkerRuntime.emittedOutputFiles.map((file) => file.path),
682		);
683		const inventoryLine = (lane: 'baseline' | 'migrated'): string =>
684			receipt.consoleErrors[lane]
685				.map((entry) => `${entry.count}x \`${entry.message.split('\n')[0]}\``)
686				.join('; ');
687		const swAnswer = (lane: 'baseline' | 'migrated'): string =>
688			WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_REQUESTS[lane]
689				.filter((entry) => entry.phase === 'response')
690				.map((entry) => `${entry.count}x \`${entry.urlPath ?? ''}\` -> ${String(entry.detail.status)}`)
691				.join(', ');
692		const failedRequestLine = (lane: 'baseline' | 'migrated'): string =>
693			receipt.failedRequests[lane]
694				.map((entry) => `${entry.count}x \`${entry.method} ${entry.path} (${entry.reason})\``)
695				.join('; ');
696		return `# HospitalRun v2.0.0-alpha.7 — direct Witness browser proof
697	
698	- Result: pass
699	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
700	- Runs: 2 baseline + 2 migrated production-static browser journeys
701	- Behavioral parity: ${receipt.runs[0]!.behaviorDigest}
702	- Journey: new-patient intake into the browser-local PouchDB store, success toast, patient row, patient record sub-tabs, labs / incidents / imaging department routes, appointment schedule with a real wheel scroll, and an online reload the created record survives
703	- Persistence: ${receipt.persistence.store}, stubbed: ${String(receipt.persistence.stubbed)}, survives an online reload: ${String(receipt.persistence.survivesOnlineReload)}
704	- Service worker: the application's own \`serviceWorker.register()\` is refused by the browser context; zero registrations, controller, CacheStorage names and worker lifecycle events at three checkpoints in every pass. The worker-script requests the application makes are not zero and are not hidden — they are recorded below.
705	- Recorded migration difference: baseline ${receipt.serviceWorkerDifference.baseline}; migrated ${receipt.serviceWorkerDifference.migrated}; masked: ${String(receipt.serviceWorkerDifference.masked)}
706	- Console-error inventory (exact, whole journey, per lane) — baseline: ${inventoryLine('baseline')}; migrated: ${inventoryLine('migrated')}
707	- Failed-request inventory (exact, whole journey, per lane) — baseline: ${failedRequestLine('baseline')}; migrated: ${failedRequestLine('migrated')}
708	- Worker-script trace: the application attempts registration ${WITNESS_REACT_HOSPITALRUN_REGISTRATION_ATTEMPTS}x per journey in both lanes and every attempt is refused; the baseline's ${swAnswer('baseline')} against the migrated build's ${swAnswer('migrated')}
709	- Retained but never-controlling worker output: ${emitted.length === 0 ? 'none' : uniqueSorted(emitted).join(', ')}
710	- Mutation proof: \`${receipt.mutation.seam}\` in \`${receipt.mutation.path}\` at offset ${receipt.mutation.offset} made the journey red, byte-identical restoration made it green again
711	- Scroll: ${receipt.scrollSurface.state} on ${receipt.scrollSurface.route} — scrollHeight ${receipt.scrollSurface.scrollHeight} against clientHeight ${receipt.scrollSurface.clientHeight} at ${receipt.scrollSurface.viewport.width}x${receipt.scrollSurface.viewport.height}
712	- React lineage readiness: unchanged at ${receipt.readiness.reactLineage.ready}/${receipt.readiness.reactLineage.total}; this vertical is not counted
713	
714	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
715	`;
716	}
717	
718	export function witnessReactHospitalrunAggregateMember(digestValue: string) {
719		return {
720			id: 'witness-react-hospitalrun',
721			framework: 'react',
722			track: 'production-readiness-direct-witness-create-react-app-to-vite8',
723			bundler: 'webpack-4.42.0-to-vite-8.0.16',
724			runtime: 'node-12.14.1-to-node-24.15.0',
725			result: 'pass',
726			receipt: WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH,
727			digest: digestValue,
728		};
729	}
730	
731	export async function verifyWitnessReactHospitalrunEvidence(rootDir = '.') {
732		const root = resolve(rootDir);
733		const receiptPath = join(root, WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH);
734		const receipt = parseWitnessReactHospitalrunReceipt(
735			JSON.parse(await readFile(receiptPath, 'utf8')),
736		);
737		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
738		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
739			throw new Error('React HospitalRun canonical receipt bytes drifted');
740		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
741			runId?: unknown;
742			fixture?: unknown;
743			integrity?: { canonicalDigest?: unknown };
744		};
745		if (
746			canonical.runId !== REACT_HOSPITALRUN_RUN_ID ||
747			canonical.fixture !== REACT_HOSPITALRUN_FIXTURE ||
748			canonical.integrity?.canonicalDigest !== receipt.canonicalReceipt.canonicalDigest
749		)
750			throw new Error('React HospitalRun canonical receipt identity differs');
751		if (
752			(await readFile(join(dirname(receiptPath), 'receipt.md'), 'utf8')) !==
753			renderWitnessReactHospitalrunReceipt(receipt)
754		)
755			throw new Error('React HospitalRun human Witness receipt differs');
756		return {
757			valid: true as const,
758			digest: receipt.integrity.canonicalDigest,
759			artifacts: 0,
760			receipt,
761		};
762	}
